INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) SELECT json_extract(value,'$[0]'),json_extract(value,'$[1]'),json_extract(value,'$[2]'),json_extract(value,'$[3]'),json_extract(value,'$[4]'),json_extract(value,'$[5]'),json_extract(value,'$[6]'),json_extract(value,'$[7]') FROM json_each('[["chunk_f80bdce276f68c1071599590","wiki/sources/trassenanmeldung-uber-das-trassenportal-netz-tpn.md",0,"Inhalt","Über das Trassenportal-Netz (TPN) können die Kund:innen (Eisenbahnverkehrsunternehmen und andere Zugangsberechtigte) online ihre Trassenanmeldungen, -änderungen und -abmeldungen abgeben und verwalten. Dadurch wird der Informationsaustausch zwischen unseren Kunden und der DB InfraGO AG beschleunigt.\r\n\r\nBestellungen können einerseits über den Internetclient erfasst und verwaltet oder über eine elektronische EVU-Schnittstelle direkt an TPN übertragen werden. Zusätzlich steht Ihnen der Internetclient auch als Webclient (nur über Google Chrome) zur Verfügung.\r\n\r\nZugriff auf das TPN über den Internetclient\r\n\r\nDie Freischaltung (User Account) zur Nutzung des Trassenportals DB InfraGO AG über den Internetclient können unsere Kund:innen über ihre Kundenbetreuung beantragen.\r\n\r\nWeitere Detailinformationen über den Internetclient stehen hier ebenfalls zum Download zur Verfügung.\r\n\r\n[Antragsformular Zugang TPN über den Internetclient (DOCX | 138,5 KB)](https://www.dbinfrago.com/resource/blob/11249642/579aaf69632303bde889896a80fd6687/antragsformular_tpn_internetclient-data.docx \"Es wird eine Datei heruntergeladen\")\r\n\r\nZugriff auf das TPN über die EVU-Schnittstelle\r\n\r\nWeitere Detailinformationen über die elektronische EVU-Schnittstelle stehen hier zum Download zur Verfügung.\r\n\r\nDetaillierte Informationen zu TPN-EVU-Schnittstellen erhalten sie über die Mailadresse [trassenportal@deutschebahn.com](mailto:trassenportal@deutschebahn.com).\r\n\r\n[Dokumentation TPN-EVU-Schnittstelle, Version 2.6.10 (gültig ab 21.02.2021) (ZIP | 1,4 MB)](https://www.dbinfrago.com/resource/blob/11249650/ed49ecdb61dfd4673df596ee800caef1/Dokumentation-TPN-EVU-Schnittstelle-Version-2-6-10-data.zip \"Es wird eine Datei heruntergeladen\")",166,"{\"canonical_url\":\"https://www.dbinfrago.com/web/schienennetz/leistungen/trassen/trassenbestellung/trassenanmeldung/trassenportal-netz-11249618\",\"normalized_sha256\":\"78d68f0333d4bddedbfdb77051a27c238ff7c7f0dc1e870f003ff434e687c391\",\"page\":null,\"source_id\":\"src_4189235db5c801f1cc06\",\"source_sha256\":\"6fea9e881dee67549dce2be1ff6a8a006e5c8ce23e005ecbe75b8facbf532860\",\"source_version_id\":\"sv_40ae35c7249fd4a5720382ff\"}","6b58bbdd482ffbe520b74f6de68fb7b1e798502aef1e2a5758fd25bef06fae1b"],["chunk_e044e11fc450606cf0168f08","wiki/sources/trassenanmeldung-uber-das-trassenportal-netz-tpn.md",1,"Inhalt","[Dokumentation TPN-EVU-Schnittstelle, Version 3.0.7 (gültig ab 21.02.2021) (ZIP | 1,4 MB)](https://www.dbinfrago.com/resource/blob/11249652/f7f6de2fc9c53d24aa2ca522431f5549/Dokumentation-TPN-EVU-Schnittstelle-Version-3-0-7-data.zip \"Es wird eine Datei heruntergeladen\")\r\n\r\n**Bitte senden Sie die ausgefüllten Antragsformulare an Ihre zuständige Kundenberatung.**",26,"{\"canonical_url\":\"https://www.dbinfrago.com/web/schienennetz/leistungen/trassen/trassenbestellung/trassenanmeldung/trassenportal-netz-11249618\",\"normalized_sha256\":\"78d68f0333d4bddedbfdb77051a27c238ff7c7f0dc1e870f003ff434e687c391\",\"page\":null,\"source_id\":\"src_4189235db5c801f1cc06\",\"source_sha256\":\"6fea9e881dee67549dce2be1ff6a8a006e5c8ce23e005ecbe75b8facbf532860\",\"source_version_id\":\"sv_40ae35c7249fd4a5720382ff\"}","a6546f30e079c6bb125504906fbe6561bd866939267ddfb72813fe61fecd9fe2"],["chunk_668108127d49ac9c251c7001","wiki/sources/unterlage-infoveranstaltung-netzfahrplan-2027-data.md",0,"Seite 1","Netzfahrplan 2027\r\n\r\nInfoveranstaltung Teilzuweisungen, Storno- und Annahmequote\r\n\r\nund E-Mailtypen\r\n\r\nApril 2026 | Frankfurt",13,"{\"canonical_url\":null,\"normalized_sha256\":\"75f0ddd23c42a7e0fe931cb72276b13df197b1ad4dc7dcd3531341c6f869f5fa\",\"page\":1,\"source_id\":\"src_5cbb3fe592ef3e699d7a\",\"source_sha256\":\"c18493521040304c96b57d131a1fc3f24a3912fa2d851db9c9686983fbd3baf9\",\"source_version_id\":\"sv_d4d4bc1ade38ec7d2950d4f6\"}","3a04224dbf1651cebd98e5363c41d21788816c2f940b4ac12112669abd45684b"],["chunk_70041418e80188fc15501c18","wiki/sources/unterlage-infoveranstaltung-netzfahrplan-2027-data.md",1,"Seite 2","Modus Operandi – Fragen? Bitte nutzen sie „F&A“ bei MS Teams\r\n\r\nDie gezeigte Unterlage wird im Nachgang verteilt\r\n\r\nSie haben Fragen im Rahmen der Veranstaltung?\r\n\r\n• In MS Teams Menüleiste das Icon „F&A“ auswählen und\r\n\r\nin das sich öffnende Fenster Ihre Frage schreiben\r\n\r\n• Bereits eingestellte Fragen voten\r\n\r\nDB InfraGO AG | Netzfahrplan 2027 - Infoveranstaltung Teilzuweisungen, Storno- und Annahmequote und E-Mailtypen | April 2026 2",66,"{\"canonical_url\":null,\"normalized_sha256\":\"75f0ddd23c42a7e0fe931cb72276b13df197b1ad4dc7dcd3531341c6f869f5fa\",\"page\":2,\"source_id\":\"src_5cbb3fe592ef3e699d7a\",\"source_sha256\":\"c18493521040304c96b57d131a1fc3f24a3912fa2d851db9c9686983fbd3baf9\",\"source_version_id\":\"sv_d4d4bc1ade38ec7d2950d4f6\"}","717d6ef806c5b4a63ee26457a59f3e87d2679865410e70314159110e43d4ede0"],["chunk_1076d20ef657e59bc199f840","wiki/sources/unterlage-infoveranstaltung-netzfahrplan-2027-data.md",2,"Seite 3","Scope\r\n\r\nNEP 2027\r\n\r\n(1) Teilzuweisung\r\n\r\n(2) Storno-/\r\n\r\nAnnahmequote\r\n\r\n(3) Mailtypen/\r\n\r\nAntwortoptionen\r\n\r\nDB InfraGO AG | Netzfahrplan 2027 - Infoveranstaltung Teilzuweisungen, Storno- und Annahmequote und E-Mailtypen | April 2026 3",29,"{\"canonical_url\":null,\"normalized_sha256\":\"75f0ddd23c42a7e0fe931cb72276b13df197b1ad4dc7dcd3531341c6f869f5fa\",\"page\":3,\"source_id\":\"src_5cbb3fe592ef3e699d7a\",\"source_sha256\":\"c18493521040304c96b57d131a1fc3f24a3912fa2d851db9c9686983fbd3baf9\",\"source_version_id\":\"sv_d4d4bc1ade38ec7d2950d4f6\"}","281008ca0536a88f620b2e86b745231fba791346697a49eb1417d89be8fc450a"],["chunk_c4650bcf877e3bbcb043a034","wiki/sources/unterlage-infoveranstaltung-netzfahrplan-2027-data.md",3,"Seite 4","Agenda\r\n\r\nStorno-/Annahmequote\r\n\r\nTeilzuweisung\r\n\r\nMailtypen/Antwortoptionen\r\n\r\nBeantwortung von Fragen\r\n\r\nDB InfraGO AG | Netzfahrplan 2027 - Infoveranstaltung Teilzuweisungen, Storno- und Annahmequote und E-Mailtypen | April 2026 4",25,"{\"canonical_url\":null,\"normalized_sha256\":\"75f0ddd23c42a7e0fe931cb72276b13df197b1ad4dc7dcd3531341c6f869f5fa\",\"page\":4,\"source_id\":\"src_5cbb3fe592ef3e699d7a\",\"source_sha256\":\"c18493521040304c96b57d131a1fc3f24a3912fa2d851db9c9686983fbd3baf9\",\"source_version_id\":\"sv_d4d4bc1ade38ec7d2950d4f6\"}","f387350652652533664700d2e81df57fdbab88c1c48c042ae9711d735a703ac5"],["chunk_5968e8bd596d2b788efe84e6","wiki/sources/unterlage-infoveranstaltung-netzfahrplan-2027-data.md",4,"Seite 5","Storno- und Annahmequote – Prozess*\r\n\r\n„Erhöhtes Storno- und\r\n\r\nStornierungsentgelt“ Annahmequote\r\n\r\nQuoten Stellungnahmen Finale Quoten\r\n\r\nabfragen prüfen abfragen festgelegt\r\n\r\n• Quoten sowie Storno-/Annahme- • Finale Quoten auf Basis der • DB InfraGO fragt Akzeptanz • Storno- und\r\n\r\ndetails werden zur Stellungnahme Stellungnahmen werden “Erhöhtes Stornierungsentgelt“ Annahmequoten\r\n\r\nan die ZB/EVU versendet durch DB InfraGO ermittelt\r\n\r\nbei ZB/EVU ab Informationen zur 1. NEP\r\n\r\n Stornoquote überschritten 2027 liegen DB InfraGO\r\n\r\n• Eingegangene Stellungnahmen der  Empfänger: ZB/EVU mit\r\n\r\nbei > 30 %\r\n\r\nZB/EVU werden durch DB InfraGO vor und werden zur\r\n\r\nüberschrittener Stornoquote\r\n\r\ngeprüft  Annahmequote 1. NEP-Bearbeitung\r\n\r\nund/oder unterschrittener\r\n\r\nunterschritten bei: < 95% verwendet\r\n\r\n• Prüfungsergebnisse inkl. ggf. Annahmequote\r\n\r\n Neu für 1. NEP 27: Quoten\r\n\r\nkorrigierte Quoten werden an die  Finale Quoten\r\n\r\nkommen zum Tragen wenn  Ziel: Verlässlichkeit ggü.\r\n\r\nZB/EVU versendet\r\n\r\nder Schwellwert in 2 von 3 DB InfraGO anzeigen  Umgang “Erhöhtes\r\n\r\nJahren über- bzw. Stornierungsentgelt“\r\n\r\nunterschritten wurde\r\n\r\n*\r\n\r\ngemäß Ziffer 4.2.1.9 lit. c) – e) der INB 2027\r\n\r\nDB InfraGO AG | Netzfahrplan 2027 - Infoveranstaltung Teilzuweisungen, Storno- und Annahmequote und E-Mailtypen | April 2026 5",179,"{\"canonical_url\":null,\"normalized_sha256\":\"75f0ddd23c42a7e0fe931cb72276b13df197b1ad4dc7dcd3531341c6f869f5fa\",\"page\":5,\"source_id\":\"src_5cbb3fe592ef3e699d7a\",\"source_sha256\":\"c18493521040304c96b57d131a1fc3f24a3912fa2d851db9c9686983fbd3baf9\",\"source_version_id\":\"sv_d4d4bc1ade38ec7d2950d4f6\"}","567aea6a8e32834ce1b52f66c5ac2c6d924a48435942f64cb904499b9b6d6012"],["chunk_78795a4f1c47344bec72948e","wiki/sources/unterlage-infoveranstaltung-netzfahrplan-2027-data.md",5,"Seite 6","Storno- und Annahmequote – ZB/EVU gilt als „nicht verlässlich“,\r\n\r\nwenn die vorgegebenen Quoten nicht eingehalten werden\r\n\r\nZB/EVU gilt als “verlässlich“\r\n\r\nAnnahmequote mind. 2 aus 3 Jahren >= 95 %\r\n\r\nA B • Keine weitere Handlung notwendig\r\n\r\n• Egal wo der Wert innerhalb der Grenzwerte liegt\r\n\r\nStornoquote mind. 2 aus 3 Jahren <= 30% (auch in Folgejahren)\r\n\r\nEVU gilt als „nicht verlässlich“\r\n\r\n• ZB/EVU wird im Konfliktfall nachrangig\r\n\r\nbehandelt ggü. jenen ZB/EVU, die die Quoten\r\n\r\nAnnahmequote mind. 2 aus 3 Jahren < 95 %*\r\n\r\neingehalten haben\r\n\r\nA B\r\n\r\n Verfügbare Kapazitäten werden zunächst\r\n\r\nunter Berücksichtigung weiterer Kriterien\r\n\r\nStornoquote mind. 2 aus 3 Jahren > 30%*\r\n\r\n(Vorrangkriterien, Regelentgelt, PaP) an\r\n\r\n*gilt auch, wenn nur eine der beiden Quoten nicht erfüllt ist\r\n\r\n“zuverlässige” ZB/EVU vergeben\r\n\r\n ggf. weitere verfügbare Kapazitäten werden\r\n\r\nanschließend unter den nachrangigen ZB/EVU\r\n\r\nvergeben (hier Rangfolge nach Quoten\r\n\r\nentsprechend INB-Regelungen)\r\n\r\nDB InfraGO AG | Netzfahrplan 2027 - Infoveranstaltung Teilzuweisungen, Storno- und Annahmequote und E-Mailtypen | April 2026 6",158,"{\"canonical_url\":null,\"normalized_sha256\":\"75f0ddd23c42a7e0fe931cb72276b13df197b1ad4dc7dcd3531341c6f869f5fa\",\"page\":6,\"source_id\":\"src_5cbb3fe592ef3e699d7a\",\"source_sha256\":\"c18493521040304c96b57d131a1fc3f24a3912fa2d851db9c9686983fbd3baf9\",\"source_version_id\":\"sv_d4d4bc1ade38ec7d2950d4f6\"}","9170bf958be2d29ba7e4e058f450d671c4e45f9bd74657efafdf8244d0bcf664"],["chunk_0e32c3e3ef7bbbb8a79fd949","wiki/sources/unterlage-infoveranstaltung-netzfahrplan-2027-data.md",6,"Seite 7","Storno-/Annahmequote – “Erhöhtes Stornierungsentgelt“\r\n\r\nErhöhtes Stornierungsentgelt\r\n\r\nDurch Akzeptanz des „Erhöhten Stornierungsentgelts“ wird die betreffende Trasse im Konflikt nicht nachrangig behandelt (sondern wie\r\n\r\neine Trasse eines ZB/EVU mit unterschrittener Storno- und überschrittener Annahmequote).\r\n\r\nIm Konfliktfall werden Vorrangkriterien, Regelentgelt und PaP zur Entscheidung herangezogen\r\n\r\n• Zielgruppe: ZB/EVU, die die Storno- und/oder Annahmequoten über- bzw. unterschreiten\r\n\r\n• Umfang: Die Abfrage des erhöhten Stornierungsentgelts umfasst entweder eine pauschale Aussage (akzeptiert für alle oder keine im\r\n\r\nKonflikt befindlichen Trassen) oder einzelne Zugnummern, die im Konfliktfall angefragt werden.\r\n\r\n• Höhe: Das erhöhte Stornierungsentgelt beträgt 70 % des Trassenentgelts laut Trassenangebot zum Netzfahrplan\r\n\r\n• Anwendung: Nur bei jenen Zeitscheiben1 die konfliktbehaftet sind und nur im Falle einer künftigen Stornierung dieser Zeitscheibe(n)1\r\n\r\nStunde 8 zeitlicher Konflikt (Jul-Aug)\r\n\r\nMo Di Mi Do Fr Sa So\r\n\r\nZug 4711\r\n\r\nZeitscheibe A B C D\r\n\r\nJul - Sep räumlicher Konflikt\r\n\r\nZug 4711\r\n\r\nZeitscheibe D\r\n\r\nA\r\n\r\nOkt - Dez\r\n\r\n1 Path Requests\r\n\r\nDB InfraGO AG | Netzfahrplan 2027 - Infoveranstaltung Teilzuweisungen, Storno- und Annahmequote und E-Mailtypen | April 2026 7",167,"{\"canonical_url\":null,\"normalized_sha256\":\"75f0ddd23c42a7e0fe931cb72276b13df197b1ad4dc7dcd3531341c6f869f5fa\",\"page\":7,\"source_id\":\"src_5cbb3fe592ef3e699d7a\",\"source_sha256\":\"c18493521040304c96b57d131a1fc3f24a3912fa2d851db9c9686983fbd3baf9\",\"source_version_id\":\"sv_d4d4bc1ade38ec7d2950d4f6\"}","dfd298897ffc8e5a93e5cf723aa025fc4feed5d13ba1489750c14efbe8ec9dbb"],["chunk_4adb51234af17f14f76fff0e","wiki/sources/unterlage-infoveranstaltung-netzfahrplan-2027-data.md",7,"Seite 8","Agenda\r\n\r\nStorno-/Annahmequote\r\n\r\nTeilzuweisung\r\n\r\nMailtypen/Antwortoptionen\r\n\r\nBeantwortung von Fragen\r\n\r\nDB InfraGO AG | Netzfahrplan 2027 - Infoveranstaltung Teilzuweisungen, Storno- und Annahmequote und E-Mailtypen | April 2026 8",25,"{\"canonical_url\":null,\"normalized_sha256\":\"75f0ddd23c42a7e0fe931cb72276b13df197b1ad4dc7dcd3531341c6f869f5fa\",\"page\":8,\"source_id\":\"src_5cbb3fe592ef3e699d7a\",\"source_sha256\":\"c18493521040304c96b57d131a1fc3f24a3912fa2d851db9c9686983fbd3baf9\",\"source_version_id\":\"sv_d4d4bc1ade38ec7d2950d4f6\"}","3c1a594752f837ce161402643dbc3c520c8458c5a453acbfd61f8dcfd9c88e0b"],["chunk_495861463f20ea04da59e68c","wiki/sources/unterlage-infoveranstaltung-netzfahrplan-2027-data.md",8,"Seite 9","Umsetzung der Teilzuweisung\r\n\r\nStunde 8 zeitlicher Konflikt\r\n\r\nMo Di Mi Do Fr Sa So\r\n\r\nAusgangslage\r\n\r\n4711 A B C D\r\n\r\nräumlicher Konflikt\r\n\r\nDB InfraGO AG | Netzfahrplan 2027 - Infoveranstaltung Teilzuweisungen, Storno- und Annahmequote und E-Mailtypen | April 2026 9",40,"{\"canonical_url\":null,\"normalized_sha256\":\"75f0ddd23c42a7e0fe931cb72276b13df197b1ad4dc7dcd3531341c6f869f5fa\",\"page\":9,\"source_id\":\"src_5cbb3fe592ef3e699d7a\",\"source_sha256\":\"c18493521040304c96b57d131a1fc3f24a3912fa2d851db9c9686983fbd3baf9\",\"source_version_id\":\"sv_d4d4bc1ade38ec7d2950d4f6\"}","301176054f54b4697aa13ff7cec54a2a03754071a7564b60d3dcaaf70c0a5003"],["chunk_048439b6e7083d08d3d05d49","wiki/sources/unterlage-infoveranstaltung-netzfahrplan-2027-data.md",9,"Seite 10","Umsetzung der Teilzuweisung\r\n\r\nStunde 8 zeitlicher Konflikt\r\n\r\nMo Di Mi Do Fr Sa So\r\n\r\nAusgangslage\r\n\r\n4711 A B C D\r\n\r\nräumlicher Konflikt\r\n\r\nVerlierer aus\r\n\r\nEntscheidungsverfahren\r\n\r\nInteresse auf\r\n\r\nTeilzuweisung bekundet?\r\n\r\nErwünscht?\r\n\r\nnein ja\r\n\r\nzeitliche + räumliche\r\n\r\nAblehnung der Trasse zeitliche Einkürzung\r\n\r\nEinkürzung\r\n\r\nA D\r\n\r\nDB InfraGO AG | Netzfahrplan 2027 - Infoveranstaltung Teilzuweisungen, Storno- und Annahmequote und E-Mailtypen | April 2026 10",61,"{\"canonical_url\":null,\"normalized_sha256\":\"75f0ddd23c42a7e0fe931cb72276b13df197b1ad4dc7dcd3531341c6f869f5fa\",\"page\":10,\"source_id\":\"src_5cbb3fe592ef3e699d7a\",\"source_sha256\":\"c18493521040304c96b57d131a1fc3f24a3912fa2d851db9c9686983fbd3baf9\",\"source_version_id\":\"sv_d4d4bc1ade38ec7d2950d4f6\"}","5dff85eaa81b21ef6847815a2f876eb0a01488bd761e91038af92f679b9f3763"],["chunk_854ef5b4c90813a0f7dbadde","wiki/sources/unterlage-infoveranstaltung-netzfahrplan-2027-data.md",10,"Seite 11","Umsetzung der Teilzuweisung – zeitliche Teilzuweisung\r\n\r\nStunde 8 zeitlicher Konflikt\r\n\r\nMo Di Mi Do Fr Sa So\r\n\r\nAusgangslage\r\n\r\n4711 A B C D\r\n\r\nräumlicher Konflikt\r\n\r\nVT Sa & So\r\n\r\nUmsetzung gesamter Laufweg Sa So\r\n\r\nzeitliche\r\n\r\nTeilzuweisung\r\n\r\nA B C D\r\n\r\nDB InfraGO AG | Netzfahrplan 2027 - Infoveranstaltung Teilzuweisungen, Storno- und Annahmequote und E-Mailtypen | April 2026 11",58,"{\"canonical_url\":null,\"normalized_sha256\":\"75f0ddd23c42a7e0fe931cb72276b13df197b1ad4dc7dcd3531341c6f869f5fa\",\"page\":11,\"source_id\":\"src_5cbb3fe592ef3e699d7a\",\"source_sha256\":\"c18493521040304c96b57d131a1fc3f24a3912fa2d851db9c9686983fbd3baf9\",\"source_version_id\":\"sv_d4d4bc1ade38ec7d2950d4f6\"}","fddd8a86c8baff71be4496fa2910a72c868c957db7d0759a7968f23e9389656a"],["chunk_2655e696fc6c3e29d4b869ac","wiki/sources/unterlage-infoveranstaltung-netzfahrplan-2027-data.md",11,"Seite 12","Umsetzung der Teilzuweisung – zeitliche und räumliche\r\n\r\nTeilzuweisung\r\n\r\nStunde 8 zeitlicher Konflikt\r\n\r\nMo Di Mi Do Fr Sa So\r\n\r\nAusgangslage\r\n\r\n4711 A B C D\r\n\r\nräumlicher Konflikt\r\n\r\nVT Sa & So\r\n\r\nUmsetzung gesamter Laufweg Sa So\r\n\r\nzeitliche\r\n\r\nTeilzuweisung\r\n\r\nA B C D\r\n\r\nSa So\r\n\r\nUmsetzung\r\n\r\nMo Di Mi Do Fr Mo Di Mi Do Fr\r\n\r\nzeitliche &\r\n\r\nräumliche\r\n\r\nA B C D\r\n\r\nTeilzuweisung\r\n\r\nDB InfraGO AG | Netzfahrplan 2027 - Infoveranstaltung Teilzuweisungen, Storno- und Annahmequote und E-Mailtypen | April 2026 12",81,"{\"canonical_url\":null,\"normalized_sha256\":\"75f0ddd23c42a7e0fe931cb72276b13df197b1ad4dc7dcd3531341c6f869f5fa\",\"page\":12,\"source_id\":\"src_5cbb3fe592ef3e699d7a\",\"source_sha256\":\"c18493521040304c96b57d131a1fc3f24a3912fa2d851db9c9686983fbd3baf9\",\"source_version_id\":\"sv_d4d4bc1ade38ec7d2950d4f6\"}","12a66a8f12a0212d910e245fbd5791449ff3bd3335cb16d37e15dc49d3316062"],["chunk_89f2ee1365582e6d04887dd9","wiki/sources/unterlage-infoveranstaltung-netzfahrplan-2027-data.md",12,"Seite 13","Abfrage zu Interesse auf Teilzuweisung\r\n\r\nAnfrage per E-Mail (Auszug)\r\n\r\nDB InfraGO AG | Netzfahrplan 2027 - Infoveranstaltung Teilzuweisungen, Storno- und Annahmequote und E-Mailtypen | April 2026 13",27,"{\"canonical_url\":null,\"normalized_sha256\":\"75f0ddd23c42a7e0fe931cb72276b13df197b1ad4dc7dcd3531341c6f869f5fa\",\"page\":13,\"source_id\":\"src_5cbb3fe592ef3e699d7a\",\"source_sha256\":\"c18493521040304c96b57d131a1fc3f24a3912fa2d851db9c9686983fbd3baf9\",\"source_version_id\":\"sv_d4d4bc1ade38ec7d2950d4f6\"}","3cd1f46bdb9fab86ad0a56840043e8ccde1aabd150f17c6eb33893770a569d17"],["chunk_4f388b275d1c0d6551882363","wiki/sources/unterlage-infoveranstaltung-netzfahrplan-2027-data.md",13,"Seite 14","Teilzuweisung – Zuweisung auf Basis der Kundenrückmeldung\r\n\r\nBeispiel\r\n\r\nStunde 8 zeitlicher Konflikt\r\n\r\nMo Di Mi Do Fr Sa So\r\n\r\nAusgangslage\r\n\r\n4711 A B C D\r\n\r\nräumlicher Konflikt\r\n\r\nAntwort per E-Mail Zuweisung\r\n\r\nA-B und C-D an Tagen Mo-Fr\r\n\r\nA-D an Tagen Sa und So\r\n\r\nVor: A-B an Tagen Mo-Fr, A-D an Tagen Sa und So\r\n\r\nNach: C-D an Tagen Mo-Fr, A-D an Tagen Sa und So\r\n\r\nA-D an Tagen Sa und So\r\n\r\nKEINE Zuweisung\r\n\r\nDB InfraGO AG | Netzfahrplan 2027 - Infoveranstaltung Teilzuweisungen, Storno- und Annahmequote und E-Mailtypen | April 2026 14",91,"{\"canonical_url\":null,\"normalized_sha256\":\"75f0ddd23c42a7e0fe931cb72276b13df197b1ad4dc7dcd3531341c6f869f5fa\",\"page\":14,\"source_id\":\"src_5cbb3fe592ef3e699d7a\",\"source_sha256\":\"c18493521040304c96b57d131a1fc3f24a3912fa2d851db9c9686983fbd3baf9\",\"source_version_id\":\"sv_d4d4bc1ade38ec7d2950d4f6\"}","4ea75fc03c92e646002b2fca4cb8f2d26bcef88747b6df81a1d4585576bbb93d"],["chunk_05bb73a4fe06a6ac44110ed2","wiki/sources/unterlage-infoveranstaltung-netzfahrplan-2027-data.md",14,"Seite 15","Teilzuweisung – Gewünschte und später vom Kunden wieder\r\n\r\nstornierte Teilzuweisungen erhöhen die Kunden-Stornoquote\r\n\r\nStornoquote\r\n\r\nsteigt\r\n\r\nAntwort per E-Mail Zuweisung Kundenstorno\r\n\r\nTZW gewünscht TZW erfolgt TZW storniert\r\n\r\nTZW nicht\r\n\r\nangenommen\r\n\r\nAnnahmequote\r\n\r\nsinkt\r\n\r\nDB InfraGO AG | Netzfahrplan 2027 - Infoveranstaltung Teilzuweisungen, Storno- und Annahmequote und E-Mailtypen | April 2026 15",49,"{\"canonical_url\":null,\"normalized_sha256\":\"75f0ddd23c42a7e0fe931cb72276b13df197b1ad4dc7dcd3531341c6f869f5fa\",\"page\":15,\"source_id\":\"src_5cbb3fe592ef3e699d7a\",\"source_sha256\":\"c18493521040304c96b57d131a1fc3f24a3912fa2d851db9c9686983fbd3baf9\",\"source_version_id\":\"sv_d4d4bc1ade38ec7d2950d4f6\"}","fe43a4e20aff5f5935e3ccfa809346c53a8d180ad13ab84f36bb2d422cad90b5"],["chunk_9bda02c0c01be9bbd8e0a847","wiki/sources/unterlage-infoveranstaltung-netzfahrplan-2027-data.md",15,"Seite 16","Agenda\r\n\r\nStorno-/Annahmequote\r\n\r\nTeilzuweisung\r\n\r\nMailtypen/Antwortoptionen\r\n\r\nBeantwortung von Fragen\r\n\r\nDB InfraGO AG | Netzfahrplan 2027 - Infoveranstaltung Teilzuweisungen, Storno- und Annahmequote und E-Mailtypen | April 2026 16",25,"{\"canonical_url\":null,\"normalized_sha256\":\"75f0ddd23c42a7e0fe931cb72276b13df197b1ad4dc7dcd3531341c6f869f5fa\",\"page\":16,\"source_id\":\"src_5cbb3fe592ef3e699d7a\",\"source_sha256\":\"c18493521040304c96b57d131a1fc3f24a3912fa2d851db9c9686983fbd3baf9\",\"source_version_id\":\"sv_d4d4bc1ade38ec7d2950d4f6\"}","f79ce68ddb23747e1a9429ca984220228fcad866b88edc982a80a61fb5844f19"],["chunk_00ff6ec15f98aff1b6acbe4f","wiki/sources/unterlage-infoveranstaltung-netzfahrplan-2027-data.md",16,"Seite 17","Mailtypen – Vorstellung der gängigsten Mailanfragen\r\n\r\nEVU\r\n\r\nDB InfraGO\r\n\r\n• Mail „vereinfachte Koordinierung im DL-Mix / TÜLS“:\r\n\r\n• Neben Gesamt-Trassenverzicht auch Anfrage auf Einkürzung/Verzicht der Trasse für den\r\n\r\nKonfliktabschnitt bzw. -zeitraum. (Sofern keine Umleitung möglich)\r\n\r\n• Mail „Abfrage auf Interesse Teilzuweisung“:\r\n\r\n• Angabe ob Interesse auf zeitliche und/oder räumliche Teilzuweisung im Konfliktabschnitt und -zeitraum\r\n\r\nbesteht.\r\n\r\n• Mail „erhöhtes Stornierungsentgelt“:\r\n\r\n• Abfrage ob erhöhtes Stornierungsentgelt für angefragten Reference Train akzeptiert wird und dadurch\r\n\r\nder Nachrang durch über bzw. unterschrittene Quote(n) ausgeglichen wird\r\n\r\n• ...\r\n\r\nDB InfraGO AG | Netzfahrplan 2027 - Infoveranstaltung Teilzuweisungen, Storno- und Annahmequote und E-Mailtypen | April 2026 17",101,"{\"canonical_url\":null,\"normalized_sha256\":\"75f0ddd23c42a7e0fe931cb72276b13df197b1ad4dc7dcd3531341c6f869f5fa\",\"page\":17,\"source_id\":\"src_5cbb3fe592ef3e699d7a\",\"source_sha256\":\"c18493521040304c96b57d131a1fc3f24a3912fa2d851db9c9686983fbd3baf9\",\"source_version_id\":\"sv_d4d4bc1ade38ec7d2950d4f6\"}","c9b756d56e402adb584a0bca6ab9c2fc835b1d510597df6ddc258ccef4f11af9"],["chunk_cac82a3ad65bc0ce11b7fd34","wiki/sources/unterlage-infoveranstaltung-netzfahrplan-2027-data.md",17,"Seite 18","Mailtypen – Was ist bei Beantwortung der Mails zu beachten?\r\n\r\nDB InfraGO\r\n\r\nEVU\r\n\r\nKeine Antwort bzw. nicht fristgerechte Antworten gelten als Ablehnung.\r\n\r\nKeine Antwort\r\n\r\nSchon aus letztem Jahr bekannt. Wer Checkboxen aus technischen Gründen\r\n\r\nnicht nutzen kann, kann auch auf andere Weise Antwort markieren.\r\n\r\nCheckbox in\r\n\r\nAntwortmails\r\n\r\nVorgegebene Fristen sind einzuhalten (Anfragen auf Verlängerungen werden von\r\n\r\nuns abgelehnt)  bei Urlaub/Krankheit/Schulung: Bitte sicherstellen, dass eine\r\n\r\nVertretung in der Abwesenheitsnotiz erwähnt ist, damit eine Weiterleitung\r\n\r\nFristen\r\n\r\nsichergestellt werden kann.\r\n\r\nKeine Abfrage mehr auf zusammenhängende Zugnummern in Bezug auf die\r\n\r\nRegelentgeltberechnung. Zusammenrechnung erfolgt nach den Voraussetzungen in\r\n\r\nEntgelt- Ziffer 4.2.1.10 der INB 2027.\r\n\r\nberechnung\r\n\r\nDB InfraGO AG | Netzfahrplan 2027 - Infoveranstaltung Teilzuweisungen, Storno- und Annahmequote und E-Mailtypen | April 2026 18",120,"{\"canonical_url\":null,\"normalized_sha256\":\"75f0ddd23c42a7e0fe931cb72276b13df197b1ad4dc7dcd3531341c6f869f5fa\",\"page\":18,\"source_id\":\"src_5cbb3fe592ef3e699d7a\",\"source_sha256\":\"c18493521040304c96b57d131a1fc3f24a3912fa2d851db9c9686983fbd3baf9\",\"source_version_id\":\"sv_d4d4bc1ade38ec7d2950d4f6\"}","03394e1443de3fff68bf5fac29b858ab9b9167ec2ac296fb81290726c80270d4"]]');
