INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) SELECT json_extract(value,'$[0]'),json_extract(value,'$[1]'),json_extract(value,'$[2]'),json_extract(value,'$[3]'),json_extract(value,'$[4]'),json_extract(value,'$[5]'),json_extract(value,'$[6]'),json_extract(value,'$[7]') FROM json_each('[["chunk_e49d6ad7f7f63b00fd50a77f","wiki/sources/unterlage-vertiefung-ujbau-27-11-data.md",18,"Seite 19","Die KOMBau beseitigt Medienbrüche und erhöht die\r\n\r\nNachvollziehbarkeit für die Kund:innen\r\n\r\nVon einer Dokumentenflut ... ...zu einem zentralen Kommunikationsmedium\r\n\r\nUnser Ziel ist die Realisierung Weiterentwicklung unter Berücksichtigung der Anforderungen\r\n\r\n• Durchgängigkeit und\r\n\r\nder Anforderungen von Kunden aus Annex VII – die KOMBau ist für die 1. Konsultationsphase\r\n\r\nHistorisierung über alle\r\n\r\ngem. Annex VII seit August 2023 in Betrieb.\r\n\r\nProzessphasen\r\n\r\nSeit Oktober 2024 wird die 2. Konsultationsphase und\r\n\r\nseit März 2025 wird die 3. Konsultationsphase über die • Integrierte Erfassung von\r\n\r\nKOMBau abgehandelt. Stellungnahmen\r\n\r\n• Bedarfsgerechte\r\n\r\nInformation mit vielfältigen\r\n\r\nFilter- und\r\n\r\nExportmöglichkeiten\r\n\r\n• Einheitliches\r\n\r\nBedienkonzept in\r\n\r\nallen Prozessphasen\r\n\r\n• Digitale Schnittstellen\r\n\r\n• Tagesscharfe Zuglaufsicht\r\n\r\nmit Berücksichtigung von\r\n\r\nMehrfachbetroffenheiten\r\n\r\n(MFB)\r\n\r\nDB InfraGO AG | EVU Informationsveranstaltung | Neuerungen im Baufahrplan 2027 | 27.11.2025 19",122,"{\"canonical_url\":null,\"normalized_sha256\":\"b8dac29882ca03410182ee1cc3877874bf2603fc3814432a56926812715f7939\",\"page\":19,\"source_id\":\"src_6564bb0ccae19080edd4\",\"source_sha256\":\"61e0fd780a0643eded9510e89a8b1c4b4f982a6742e50fb2379ef7390cde57e3\",\"source_version_id\":\"sv_9911c8dfe35973048b5d6173\"}","ed011963fde59ab904eea762a12f1d5160e2b84b5be5fed76436987356458e69"],["chunk_4daaf404feb3460a0a33b0c3","wiki/sources/unterlage-vertiefung-ujbau-27-11-data.md",19,"Seite 20","Konsultation mittels KOMBau nach Regelprozess im\r\n\r\nMigrationsjahr 2027\r\n\r\nFplj 2027\r\n\r\nDas GPE (Grobplanungsergebnis) zeigt geplante Änderungen an einer Trasse.\r\n\r\nKOMBau zeigt das GPE unverändert an und wird in Zukunft die Unterschiede\r\n\r\nz-24 GPE\r\n\r\nzur ursprünglich bestellten Trasse hervorheben.\r\n\r\nDurch eine SN (Stellungnahme) kann ein Zugangsberechtigter detailliert auf das\r\n\r\nz-21 Annahme SN Ablehnung\r\n\r\nGPE der DB InfraGO reagieren. Neben einer Stellungnahme sind auch eine\r\n\r\nAnnahme oder eine Ablehnung des GPE möglich.\r\n\r\nDas GPEnS (Grobplanungsergebnis nach Stellungnahme) ist die von DB\r\n\r\nz-15 GPEnS\r\n\r\nInfraGO geprüfte und überarbeitete Trassenplanung nach der\r\n\r\nStellungnahmephase. Es enthält alle umsetzbaren Änderungswünsche und zeigt\r\n\r\ndie neue geplante Trassenführung. ZB können es nur annehmen oder ablehnen,\r\n\r\nz-14 Annahme Ablehnung jedoch nicht erneut kommentieren.\r\n\r\nFPE FPE Das FPE (Feinplanungsergebnis) markiert den Abschluss des\r\n\r\nz-8 (Trasse wird (Trasse wird\r\n\r\nÄnderungsprozesses und zeigt die endgültige Trassenführung mit finalen\r\n\r\nkonstruiert) storniert)\r\n\r\nFahrzeiten und bestätigten Betroffenheiten.\r\n\r\nDB InfraGO AG | EVU Informationsveranstaltung | Neuerungen im Baufahrplan 2027 | 27.11.2025 20",156,"{\"canonical_url\":null,\"normalized_sha256\":\"b8dac29882ca03410182ee1cc3877874bf2603fc3814432a56926812715f7939\",\"page\":20,\"source_id\":\"src_6564bb0ccae19080edd4\",\"source_sha256\":\"61e0fd780a0643eded9510e89a8b1c4b4f982a6742e50fb2379ef7390cde57e3\",\"source_version_id\":\"sv_9911c8dfe35973048b5d6173\"}","be555435aa91aabc7f04255996274582111209bcdf7c0418d43dec2667cde123"],["chunk_edee05a8b8563613548df56f","wiki/sources/unterlage-vertiefung-ujbau-27-11-data.md",20,"Seite 21","Detailansicht\r\n\r\nGrobplanungsergebnis (GPE) [z-24]\r\n\r\nDefinition Fahrplanprodukt 1\r\n\r\n• Das GPE zeigt geplante Änderungen an einer\r\n\r\nTrasse\r\n\r\n• Veröffentlichung: Montags 06:00 Uhr als\r\n\r\n2\r\n\r\nPathDetailsMessage in KOMBau\r\n\r\n• Stornierungen: per PathNotAvailableMessage\r\n\r\n• KOMBau zeigt GPE unverändert an und wird\r\n\r\nzukünftig Unterschiede zur ursprünglich bestellten\r\n\r\nTrasse hervorheben\r\n\r\nDetails Screenshot\r\n\r\n1• Zentrale Übersichtsseite mit detaillierter Ansicht\r\n\r\nrelevanter Trassen\r\n\r\n→ Zugriff über Navigationspunkt „GPE & FPE“\r\n\r\n• Darstellung der Trassendaten in Tabellenform\r\n\r\n2\r\n\r\n→ eine Zeile pro Trasse mit relevanten Trasseninformationen für schnellen Überblick\r\n\r\n• Strukturierte Themenblöcke erleichtern Analyse\r\n\r\n/\r\n\r\nund Bearbeitung\r\n\r\nHinweis: Die dargestellten Inhalte und Daten sind rein fiktiv und entsprechen keiner realen Planung.\r\n\r\nDB InfraGO AG | EVU Informationsveranstaltung | Neuerungen im Baufahrplan 2027 | 27.11.2025 21",116,"{\"canonical_url\":null,\"normalized_sha256\":\"b8dac29882ca03410182ee1cc3877874bf2603fc3814432a56926812715f7939\",\"page\":21,\"source_id\":\"src_6564bb0ccae19080edd4\",\"source_sha256\":\"61e0fd780a0643eded9510e89a8b1c4b4f982a6742e50fb2379ef7390cde57e3\",\"source_version_id\":\"sv_9911c8dfe35973048b5d6173\"}","0ba1074ad9416bd0d9dce76135a4093c46e1a0ca36d2153800dccd07dad3c306"],["chunk_b94e1b6675175b945546e74e","wiki/sources/unterlage-vertiefung-ujbau-27-11-data.md",21,"Seite 22","Detailansicht\r\n\r\nGrobplanungsergebnis (GPE) [z-24]\r\n\r\nDefinition Fahrplanprodukt\r\n\r\n• Das GPE zeigt geplante Änderungen an einer\r\n\r\nTrasse\r\n\r\n• Veröffentlichung: Montags 06:00 Uhr als\r\n\r\nPathDetailsMessage in KOMBau\r\n\r\n2\r\n\r\n• Stornierungen: per PathNotAvailableMessage\r\n\r\n• KOMBau zeigt GPE unverändert an und wird\r\n\r\n3\r\n\r\nzukünftig Unterschiede zur ursprünglich bestellten\r\n\r\nTrasse hervorheben\r\n\r\nDetails Screenshot 1\r\n\r\n• Detaillierte Darstellung eines\r\n\r\n1\r\n\r\nPlanungsergebnisses mit Laufweg,\r\n\r\nLaufwegspunkten und Zugcharakteristik\r\n\r\n• Enthält direkte Hinweise und Anmerkungen der\r\n\r\n2\r\n\r\nDB InfraGO\r\n\r\n3• Verlinkungen zu Baukapazitätseinschränkungen\r\n\r\n• Zukünftig: Vergleich zwischen Planungsergebnis\r\n\r\n/\r\n\r\nund Regeltrasse\r\n\r\nHinweis: Die dargestellten Inhalte und Daten sind rein fiktiv und entsprechen keiner realen Planung.\r\n\r\nDB InfraGO AG | EVU Informationsveranstaltung | Neuerungen im Baufahrplan 2027 | 27.11.2025 22",109,"{\"canonical_url\":null,\"normalized_sha256\":\"b8dac29882ca03410182ee1cc3877874bf2603fc3814432a56926812715f7939\",\"page\":22,\"source_id\":\"src_6564bb0ccae19080edd4\",\"source_sha256\":\"61e0fd780a0643eded9510e89a8b1c4b4f982a6742e50fb2379ef7390cde57e3\",\"source_version_id\":\"sv_9911c8dfe35973048b5d6173\"}","ee1dc4530ff9bf0a15c9ab5bfcb31bfcccf8ad467f3b530775a884b106ddcfe0"],["chunk_1bb2deb651885a46fa876da6","wiki/sources/unterlage-vertiefung-ujbau-27-11-data.md",22,"Seite 23","Detailansicht\r\n\r\nStellungnahme (SN) [z-21]\r\n\r\n1\r\n\r\nDefinition Fahrplanprodukt\r\n\r\n• Durch das Verfassen einer SN (Stellungnahme)\r\n\r\nkann ein Zugangsberechtigter detailliert auf das\r\n\r\nGPE (Grobplanungsergebnis) der DB InfraGO\r\n\r\n2\r\n\r\nreagieren.\r\n\r\n• Der Zeitraum für Stellungnahmen umfasst drei\r\n\r\nWochen (z-24 bis z-21).\r\n\r\n• Neben einer Stellungnahme sind auch eine\r\n\r\nAnnahme oder eine Ablehnung des GPE möglich.\r\n\r\nDetails Screenshot\r\n\r\n1• Anpassung von Laufwegen (Umleitungen und\r\n\r\nTeilausfälle)\r\n\r\n• Anpassung von Laufwegspunktangaben wie\r\n\r\n2\r\n\r\nAnkunft und Abfahrtzeiten, Haltedauern,\r\n\r\n3\r\n\r\nStreckenpunktangaben, Haltearten\r\n\r\n• Anpassung von Zugaktivitäten und\r\n\r\n3\r\n\r\nZugcharakteristiken\r\n\r\nHinweis: Die dargestellten Inhalte und Daten sind rein fiktiv und entsprechen keiner realen Planung.\r\n\r\nDB InfraGO AG | EVU Informationsveranstaltung | Neuerungen im Baufahrplan 2027 | 27.11.2025 23",109,"{\"canonical_url\":null,\"normalized_sha256\":\"b8dac29882ca03410182ee1cc3877874bf2603fc3814432a56926812715f7939\",\"page\":23,\"source_id\":\"src_6564bb0ccae19080edd4\",\"source_sha256\":\"61e0fd780a0643eded9510e89a8b1c4b4f982a6742e50fb2379ef7390cde57e3\",\"source_version_id\":\"sv_9911c8dfe35973048b5d6173\"}","460411e07b0bcc1fd760c045363d5a427f1742af962221753faa5c1c3985baf1"],["chunk_60191391b18dbb20ecf61a3d","wiki/sources/unterlage-vertiefung-ujbau-27-11-data.md",23,"Seite 24","Detailansicht\r\n\r\nStellungnahme (SN) [z-21]\r\n\r\nDefinition Fahrplanprodukt\r\n\r\n• Durch das Verfassen einer SN (Stellungnahme)\r\n\r\nkann ein Zugangsberechtigter detailliert auf das\r\n\r\nGPE (Grobplanungsergebnis) der DB InfraGO\r\n\r\n1 2\r\n\r\nreagieren.\r\n\r\n• Der Zeitraum für Stellungnahmen umfasst drei\r\n\r\nWochen (z-24 bis z-21).\r\n\r\n• Neben einer Stellungnahme sind auch eine\r\n\r\nAnnahme oder eine Ablehnung des GPE möglich.\r\n\r\nDetails Screenshot\r\n\r\n1• Einbinden neuer möglicher Laufwege, um\r\n\r\nKundenwünsche so genau wie möglich\r\n\r\nabzubilden\r\n\r\n2• Direkte Visualisierung in den Laufweg der\r\n\r\nStellungnahme\r\n\r\n/• Modalentwicklung gemeinsam mit dem Markt\r\n\r\nHinweis: Die dargestellten Inhalte und Daten sind rein fiktiv und entsprechen keiner realen Planung.\r\n\r\nDB InfraGO AG | EVU Informationsveranstaltung | Neuerungen im Baufahrplan 2027 | 27.11.2025 24",108,"{\"canonical_url\":null,\"normalized_sha256\":\"b8dac29882ca03410182ee1cc3877874bf2603fc3814432a56926812715f7939\",\"page\":24,\"source_id\":\"src_6564bb0ccae19080edd4\",\"source_sha256\":\"61e0fd780a0643eded9510e89a8b1c4b4f982a6742e50fb2379ef7390cde57e3\",\"source_version_id\":\"sv_9911c8dfe35973048b5d6173\"}","91cb833bae92d5e8d321f3768da04a41bde84d4304da075aba6c628b74fd5178"],["chunk_82bee7690c79a99db2bfd7f2","wiki/sources/unterlage-vertiefung-ujbau-27-11-data.md",24,"Seite 25","Detailansicht\r\n\r\nGrobplanungsergebnis nach Stellungnahme (GPEnS) [z-15]\r\n\r\nDefinition Fahrplanprodukt\r\n\r\n• Das GPEnS ist die von DB InfraGO geprüfte und\r\n\r\nüberarbeitete Trassenplanung nach der Stellungnahmephase. Es enthält alle bestätigten Änder-\r\n\r\n1 2\r\n\r\nungen und zeigt die neu geplante Trassenführung.\r\n\r\n• ZB können es innerhalb einer Woche annehmen\r\n\r\noder ablehnen, jedoch nicht erneut kommentieren.\r\n\r\n• Bereitstellung: Montags 06:00 Uhr als\r\n\r\nPathDetailsMessage.\r\n\r\nDetails Screenshot\r\n\r\n1• Navigation in die vergangene „Meine SN“ oder\r\n\r\nauch GPE\r\n\r\n• Darstellung des aktuellen Prozessschrittes im\r\n\r\n2\r\n\r\nWorkflow-Assistent der Detailseite als auch\r\n\r\nÜbersichtsseite\r\n\r\n/• Aufbau identisch zur GPE\r\n\r\n• Laufweg\r\n\r\n• Laufwegspunktangaben\r\n\r\n• Zugcharakterisitik\r\n\r\nHinweis: Die dargestellten Inhalte und Daten sind rein fiktiv und entsprechen keiner realen Planung.\r\n\r\nDB InfraGO AG | EVU Informationsveranstaltung | Neuerungen im Baufahrplan 2027 | 27.11.2025 25",122,"{\"canonical_url\":null,\"normalized_sha256\":\"b8dac29882ca03410182ee1cc3877874bf2603fc3814432a56926812715f7939\",\"page\":25,\"source_id\":\"src_6564bb0ccae19080edd4\",\"source_sha256\":\"61e0fd780a0643eded9510e89a8b1c4b4f982a6742e50fb2379ef7390cde57e3\",\"source_version_id\":\"sv_9911c8dfe35973048b5d6173\"}","e7a77abcd78a43845175e9b9134da636387d02e025017c6899de10234f0378d4"],["chunk_966ebde67feb92d3c8a89a9e","wiki/sources/unterlage-vertiefung-ujbau-27-11-data.md",25,"Seite 26","Exkurs\r\n\r\nZustimmen & Ablehnen GPE / GPEnS [z-21 / z-14]\r\n\r\nFristigkeiten\r\n\r\n• GPE (3 Wochen Frist)\r\n\r\n• Stellungnahme verfassen\r\n\r\n1\r\n\r\n• Ablehnen\r\n\r\n• Zustimmen\r\n\r\n• GPEnS (1 Woche Frist)\r\n\r\n• Ablehnen\r\n\r\n• Zustimmen\r\n\r\nDetails Screenshot\r\n\r\n1• Solange die Frist aktiv ist, kann der Status\r\n\r\nverändert werden\r\n\r\n• Übergabe an DB InfraGO erst nach Ablauf der\r\n\r\n/\r\n\r\nFrist\r\n\r\nAblehnen Zustimmen\r\n\r\nHinweis: Die dargestellten Inhalte und Daten sind rein fiktiv und entsprechen keiner realen Planung.\r\n\r\nDB InfraGO AG | EVU Informationsveranstaltung | Neuerungen im Baufahrplan 2027 | 27.11.2025 26",87,"{\"canonical_url\":null,\"normalized_sha256\":\"b8dac29882ca03410182ee1cc3877874bf2603fc3814432a56926812715f7939\",\"page\":26,\"source_id\":\"src_6564bb0ccae19080edd4\",\"source_sha256\":\"61e0fd780a0643eded9510e89a8b1c4b4f982a6742e50fb2379ef7390cde57e3\",\"source_version_id\":\"sv_9911c8dfe35973048b5d6173\"}","6a6033e56ab521f5973a993f1106b0d0dd6e49f9508fab5afd5e938e672c3e52"],["chunk_7eece4569cb6696e0ba3b52e","wiki/sources/unterlage-vertiefung-ujbau-27-11-data.md",26,"Seite 27","Detailansicht\r\n\r\nFeinplanungsergebnis (FPE) [z-8]\r\n\r\nDefinition Fahrplanprodukt\r\n\r\n• Das FPE (Feinplanungsergebnis) markiert den\r\n\r\nAbschluss des Änderungsprozesses und zeigt die\r\n\r\n1\r\n\r\nendgültige Trassenführung mit finalen Fahrzeiten\r\n\r\nund bestätigten Betroffenheiten.\r\n\r\n• Bereitstellung: Unmittelbar nach Erhalt als\r\n\r\nPathDetailsMessage in KOMBau\r\n\r\nDetails Screenshot\r\n\r\n1• Gleicher Aufbau wie bei einer GPE oder GPEnS\r\n\r\n• Dient der reinen Information ohne Möglichkeit\r\n\r\n/\r\n\r\neine Stellungnahme abzugeben\r\n\r\n• Historisierung des Abstimmungsprozess\r\n\r\n/\r\n\r\nweiterhin gegeben\r\n\r\nHinweis: Die dargestellten Inhalte und Daten sind rein fiktiv und entsprechen keiner realen Planung.\r\n\r\nDB InfraGO AG | EVU Informationsveranstaltung | Neuerungen im Baufahrplan 2027 | 27.11.2025 27",93,"{\"canonical_url\":null,\"normalized_sha256\":\"b8dac29882ca03410182ee1cc3877874bf2603fc3814432a56926812715f7939\",\"page\":27,\"source_id\":\"src_6564bb0ccae19080edd4\",\"source_sha256\":\"61e0fd780a0643eded9510e89a8b1c4b4f982a6742e50fb2379ef7390cde57e3\",\"source_version_id\":\"sv_9911c8dfe35973048b5d6173\"}","32dd7014fb0bc302d6d1366337bd254504f2151f7dbbf381cc15682f80bee686"],["chunk_50c354694cbcf46a7e42feb8","wiki/sources/unterlage-vertiefung-ujbau-27-11-data.md",27,"Seite 28","Informationen zur KOMBau\r\n\r\nDie jeweils aktuellen Release Notes mit\r\n\r\nBeschreibung der neuen Funktionalitäten (und\r\n\r\nweiteren Optimierungen und Fehlerbehebungen)\r\n\r\nsowie die aktualisierte Bedienungsanleitung sind\r\n\r\nwie gewohnt veröffentlicht unter:\r\n\r\nKOMBau Info (Internet)\r\n\r\nBei fachlichen Fragen, Fehlermeldungen und\r\n\r\nAnmerkungen zum Inhalt der KOMBau wenden\r\n\r\nSie sich bitte an:\r\n\r\n[E-Mail-Adresse entfernt]\r\n\r\nDB InfraGO AG | EVU Informationsveranstaltung | Neuerungen im Baufahrplan 2027 | 27.11.2025 2288",61,"{\"canonical_url\":null,\"normalized_sha256\":\"b8dac29882ca03410182ee1cc3877874bf2603fc3814432a56926812715f7939\",\"page\":28,\"source_id\":\"src_6564bb0ccae19080edd4\",\"source_sha256\":\"61e0fd780a0643eded9510e89a8b1c4b4f982a6742e50fb2379ef7390cde57e3\",\"source_version_id\":\"sv_9911c8dfe35973048b5d6173\"}","b70d40f6f20aa1bd661785652fbf41bf99d6efffa409cc8d8fa1e46c656667b5"],["chunk_0ca85638b0447a29cccccb44","wiki/sources/unterlage-vertiefung-ujbau-27-11-data.md",28,"Seite 29","Digitale BauFplo\r\n\r\nStartschuss für den Hochlauf in 2026\r\n\r\nDB InfraGO AG | EVU Informationsveranstaltung | Neuerungen im Baufahrplan 2027 | 27.11.2025 29",22,"{\"canonical_url\":null,\"normalized_sha256\":\"b8dac29882ca03410182ee1cc3877874bf2603fc3814432a56926812715f7939\",\"page\":29,\"source_id\":\"src_6564bb0ccae19080edd4\",\"source_sha256\":\"61e0fd780a0643eded9510e89a8b1c4b4f982a6742e50fb2379ef7390cde57e3\",\"source_version_id\":\"sv_9911c8dfe35973048b5d6173\"}","6d5e2c45eca7f63f87ecf420812ba5901d1226c42f2f799afe683ad7c8449ffd"],["chunk_700c65e96f9602132596da3f","wiki/sources/unterlage-vertiefung-ujbau-27-11-data.md",29,"Seite 30","Unter Berücksichtigung der Anforderungen von TTT / Annex VII\r\n\r\nwerden neue unterjährige Fahrplanprodukte eingeführt\r\n\r\nMigrationszeitraum Fplj 2027: Übersicht Fahrplanprodukte und zugehörige Prozesse\r\n\r\n3\r\n\r\nGPE1 GPEnS2 FPE3 NAÄ4 BauFplo5\r\n\r\nInfraGO\r\n\r\nz-24 z-15 z-8 z-8 bis z-3\r\n\r\nWebportal\r\n\r\nWebanwendung KOMBau PDF per Mail\r\n\r\nSysteme pathOS\r\n\r\nCommon Interface pathOS (Schnittstelle zur Trassenmeldung) API\r\n\r\nEVU\r\n\r\nStellungnahme\r\n\r\nz-21\r\n\r\n3 Digitale BauFplo / Durchführungsdokument\r\n\r\n(1) Grobplanungsergebnis (2) Grobplanungsergebnis nach Stellungnahme (3) Feinplanungsergebnis (4) Netzausgelöste Änderung (5) Baufahrplananordnung\r\n\r\nDB InfraGO AG | EVU Informationsveranstaltung | Neuerungen im Baufahrplan 2027 | 27.11.2025 30",85,"{\"canonical_url\":null,\"normalized_sha256\":\"b8dac29882ca03410182ee1cc3877874bf2603fc3814432a56926812715f7939\",\"page\":30,\"source_id\":\"src_6564bb0ccae19080edd4\",\"source_sha256\":\"61e0fd780a0643eded9510e89a8b1c4b4f982a6742e50fb2379ef7390cde57e3\",\"source_version_id\":\"sv_9911c8dfe35973048b5d6173\"}","b36900381a788148cedb8bcfbeec12a4f28155968e24128721e8c65489f97c54"],["chunk_db8f29c6d40503a818c04d63","wiki/sources/unterlage-vertiefung-ujbau-27-11-data.md",30,"Seite 31","Die digitale BauFplo reiht sich in die neue Fahrplanwelt ein und\r\n\r\nerzielt positive Effekte bei Digitalisierung und Betrieb\r\n\r\nVON ZU\r\n\r\nSicht auf einzelne Baumaßnahmen je BauFplo Sicht auf gesamte Zugfahrt je BauFplo\r\n\r\n→ Keine Gesamtsicht → Überregionale Sicht (Start bei Ziel)\r\n\r\nLogik\r\n\r\n→ Mehrere BauFplo pro Zugfahrt → Eine BauFplo pro Zug und Verkehrstag\r\n\r\nKeine unterstützte Schnittstelle Direkte Anbindung an Daten-Schnittstelle\r\n\r\n→ PDF sowie xml-Datensätze, ohne → Maschinenlesbare Formate (xml, json)\r\n\r\nFormat\r\n\r\nGewährleistung, möglich zusätzlich zu PDF\r\n\r\nHoher manueller Aufwand in der Erstellung Automatische Erstellung\r\n\r\n→ Hohe Fehlerquote bei Erstellung → Fehlerquellen systemisch ausgeschlossen\r\n\r\nSchnittstelle\r\n\r\n→ Händisches Zusammenstellen für Zugfahrt → Geringerer Aufwand bei InfraGO und EVU\r\n\r\nGeringe EBuLa-Quote Nahezu 100% EBuLa-Quote\r\n\r\nDaten-\r\n\r\n→ Hohe Anzahl an Sonderlösungen zur digitalen → Standardformat EBuLa\r\n\r\nqualität\r\n\r\nDarstellung von Fplo\r\n\r\nDB InfraGO AG | EVU Informationsveranstaltung | Neuerungen im Baufahrplan 2027 | 27.11.2025 31",141,"{\"canonical_url\":null,\"normalized_sha256\":\"b8dac29882ca03410182ee1cc3877874bf2603fc3814432a56926812715f7939\",\"page\":31,\"source_id\":\"src_6564bb0ccae19080edd4\",\"source_sha256\":\"61e0fd780a0643eded9510e89a8b1c4b4f982a6742e50fb2379ef7390cde57e3\",\"source_version_id\":\"sv_9911c8dfe35973048b5d6173\"}","288e953fe1ae178af6cd7aaf717d5529fd4a328574f4d55c7f7388f8ee13c8a9"],["chunk_0b3ecb8be19c7dbacb3aa93a","wiki/sources/unterlage-vertiefung-ujbau-27-11-data.md",31,"Seite 32","Exkurs: Gegenüberstellung BauFplo alt vs. BauFplo neu\r\n\r\nVON ZU\r\n\r\n1\r\n\r\nEine Baumaßnahme\r\n\r\nEine\r\n\r\nZugnummer\r\n\r\n1-n Bau-\r\n\r\nMehrere\r\n\r\nmaßnahmen\r\n\r\nZugnummern\r\n\r\nHinweis: Die dargestellten Inhalte und Daten sind rein fiktiv und entsprechen keiner realen Planung.\r\n\r\n(1) Aktuelles Format der digitalen BauFplo\r\n\r\nDB InfraGO AG | EVU Informationsveranstaltung | Neuerungen im Baufahrplan 2027 | 27.11.2025 32",53,"{\"canonical_url\":null,\"normalized_sha256\":\"b8dac29882ca03410182ee1cc3877874bf2603fc3814432a56926812715f7939\",\"page\":32,\"source_id\":\"src_6564bb0ccae19080edd4\",\"source_sha256\":\"61e0fd780a0643eded9510e89a8b1c4b4f982a6742e50fb2379ef7390cde57e3\",\"source_version_id\":\"sv_9911c8dfe35973048b5d6173\"}","265ae8904ab9dac0ca15acef064ad00a2918ca70a27992332e771e2b8227054b"],["chunk_b2e9c3e19a6a83e847d394a2","wiki/sources/unterlage-vertiefung-ujbau-27-11-data.md",32,"Seite 33","Mit der Betriebserprobung bereiten wir sukzessive die\r\n\r\nEinführung der digitalen BauFplo in 2026 vor\r\n\r\nEinblick in die laufende Betriebserprobung\r\n\r\nStand 26.11.25\r\n\r\n107\r\n\r\n107 7\r\n\r\nbeantwortete Fragen &\r\n\r\nveröffentlichte BauFplon teilnehmende EVU\r\n\r\nVeröffentlichung im FAQ\r\n\r\n5 von 7 8 12\r\n\r\nRegionen sind Teil der Erprobung EVU in Vorgesprächen verprobte Anwendungsfälle\r\n\r\nDB InfraGO AG | EVU Informationsveranstaltung | Neuerungen im Baufahrplan 2027 | 27.11.2025 33",63,"{\"canonical_url\":null,\"normalized_sha256\":\"b8dac29882ca03410182ee1cc3877874bf2603fc3814432a56926812715f7939\",\"page\":33,\"source_id\":\"src_6564bb0ccae19080edd4\",\"source_sha256\":\"61e0fd780a0643eded9510e89a8b1c4b4f982a6742e50fb2379ef7390cde57e3\",\"source_version_id\":\"sv_9911c8dfe35973048b5d6173\"}","592be03fe4dde14247137f58c5d0b3396602d474c5d7445e240b04e22bd2769b"],["chunk_19c008f7cdf3f22538369515","wiki/sources/unterlage-vertiefung-ujbau-27-11-data.md",33,"Seite 34","Die DB InfraGO bietet eine unterstützte XML-Schnittstelle zum\r\n\r\ndigitalen Abruf und Verarbeiten der BauFplo an\r\n\r\nDigitaler Datenabruf der BauFplo\r\n\r\nAnfrage EVU: Antwort EIU:\r\n\r\nAbruf BauFplo Digitale BauFplo\r\n\r\ngefiltert nach Zug dieses Zuges an\r\n\r\nund Tag diesem Tag\r\n\r\nBeschreibung\r\n\r\n• Verfügbar sind sämtliche in der PDF vorhandenen\r\n\r\nAttribute\r\n\r\n• Ein Datensatz entspricht einem Zug\r\n\r\n• Eine Schnittstellendokumentation sowie eine Anleitung\r\n\r\nfür den Testzugang zur BauFplo API sind über unsere\r\n\r\nWebsite abrufbar\r\n\r\nDB InfraGO AG | EVU Informationsveranstaltung | Neuerungen im Baufahrplan 2027 | 27.11.2025 34",84,"{\"canonical_url\":null,\"normalized_sha256\":\"b8dac29882ca03410182ee1cc3877874bf2603fc3814432a56926812715f7939\",\"page\":34,\"source_id\":\"src_6564bb0ccae19080edd4\",\"source_sha256\":\"61e0fd780a0643eded9510e89a8b1c4b4f982a6742e50fb2379ef7390cde57e3\",\"source_version_id\":\"sv_9911c8dfe35973048b5d6173\"}","82770522dfac0c6cc9e9762dbd73a2f589d90b1b9ef59b69fb9a3d54218bdfe0"],["chunk_367c81342eef83e74e24079d","wiki/sources/unterlage-vertiefung-ujbau-27-11-data.md",34,"Seite 35","Mit Einführung des Annex VII im uj Bau löst die digitale BauFplo\r\n\r\ndie bisherige BauFplo Ende 2026 vollständig ab\r\n\r\nRollout digitale BauFplo 2025-2027\r\n\r\n2025 2026 2027\r\n\r\nJan. Febr. März Apr. Mai Juni Juli Aug. Sept. Okt. Nov. Dez. Jan. Febr. März Apr. Mai Juni Juli Aug. Sept. Okt. Nov. Dez. Jan. Febr.\r\n\r\nWichtig: Da es sich bei\r\n\r\nder BauFplo um ein\r\n\r\nBetriebserprobung\r\n\r\nkritisches Fahrplan-\r\n\r\n100%\r\n\r\nprodukt handelt, darf\r\n\r\ndigitale\r\n\r\nein Zug nur in einem\r\n\r\nBauFplo\r\n\r\nFormat kommuniziert\r\n\r\nHochlauf möglich werden, um die Datenkonsistenz und damit\r\n\r\ndie Sicherheit zu\r\n\r\nwahren.\r\n\r\n10/2026\r\n\r\nSchnittstellen-Spezifikation\r\n\r\nHochlauf digitale BauFplo in Finale\r\n\r\nsteht zur Verfügung: EVU-\r\n\r\nAbstimmung mit EVU möglich Umstellung\r\n\r\nseitige Entwicklung möglich\r\n\r\nDB InfraGO AG | EVU Informationsveranstaltung | Neuerungen im Baufahrplan 2027 | 27.11.2025 35",122,"{\"canonical_url\":null,\"normalized_sha256\":\"b8dac29882ca03410182ee1cc3877874bf2603fc3814432a56926812715f7939\",\"page\":35,\"source_id\":\"src_6564bb0ccae19080edd4\",\"source_sha256\":\"61e0fd780a0643eded9510e89a8b1c4b4f982a6742e50fb2379ef7390cde57e3\",\"source_version_id\":\"sv_9911c8dfe35973048b5d6173\"}","881f2d59e0d0d523bffe825c6e862c50082f247c7421c9def586e525159c3450"],["chunk_37bf3589846b250c840a1a97","wiki/sources/unterlage-vertiefung-ujbau-27-11-data.md",35,"Seite 36","Die Umstellung auf die neue BauFplo ist alternativlos und\r\n\r\nbringt Veränderungen für die EVU mit sich\r\n\r\nAuf neuer Logik Systemseitige Anpassungen Veränderte Prozesse und\r\n\r\naufbauen vornehmen Kommunikation umsetzen\r\n\r\nFinale Umstellung\r\n\r\n− Mehrzahl an Dokumenten aufgrund − Anbindung an Schnittstelle − Zuglauf muss nicht mehr aus\r\n\r\nvon neuer Logik: Nicht mehr eine empfohlen einzelnen Sammel-Fplon\r\n\r\nBauFplo je Baumaßnahme, sondern zusammengesetzt werden, sondern\r\n\r\neine BauFplo je Zug und Verkehrstag − PDF Versand erfolgt weiterhin (im wird als gesamthaftes Dokument\r\n\r\nneuen Format) bereitgestellt\r\n\r\nHochlauf 2026\r\n\r\n− Bei Teilnahme an der − Im Hochlauf Parallelbetrieb beider − Befähigung Betriebsabläufe,\r\n\r\nBetriebserprobung und im Hochlauf Systeme und Prüfung der EVU- Disposition und Tf schon jetzt\r\n\r\nist es notwendig, mit beiden seitigen Systemlandschaft (z.B. sicherstellen\r\n\r\nFormaten umgehen zu können Abrechnungssysteme)\r\n\r\nAuch wenn seitens EVU keine techn. Anbindung an Schnittstelle erfolgt, wird mit der Einführung von Annex VII und der\r\n\r\ndigit. BauFplo ab Q4/26 ausschließlich das neue Format mit Trassensicht, bestehend aus PDF und API, bereitgestellt.\r\n\r\nDB InfraGO AG | EVU Informationsveranstaltung | Neuerungen im Baufahrplan 2027 | 27.11.2025 36",172,"{\"canonical_url\":null,\"normalized_sha256\":\"b8dac29882ca03410182ee1cc3877874bf2603fc3814432a56926812715f7939\",\"page\":36,\"source_id\":\"src_6564bb0ccae19080edd4\",\"source_sha256\":\"61e0fd780a0643eded9510e89a8b1c4b4f982a6742e50fb2379ef7390cde57e3\",\"source_version_id\":\"sv_9911c8dfe35973048b5d6173\"}","34436c19af9dba03e2423189aba7900d1f22bcbe34b9b2487252373b70294c3f"],["chunk_7a8970e678c277d03ffd98bf","wiki/sources/unterlage-vertiefung-ujbau-27-11-data.md",36,"Seite 37","Jetzt an der Betriebserprobung teilnehmen und die Vorteile der\r\n\r\ndigitalen BauFplo kennenlernen!\r\n\r\nEckpunkte und Inhalte der Betriebserprobung So funktioniert die Teilnahme\r\n\r\nCheckliste\r\n\r\nTrasse und zugehörige Kontakt aufnehmen über\r\n\r\nFahrplananordnung wird individuell [E-Mail-Adresse entfernt]\r\n\r\nausgewählt\r\n\r\nVereinbarung eines Info-Termins und\r\n\r\nBesprechung des weiteren Vorgehens\r\n\r\nAbstimmung je nach Konstellation zwischen\r\n\r\nGemeinsame Trassenauswahl\r\n\r\nKonstrukteur und EVU notwendig\r\n\r\nTrassenauswahl für bestimmte Anwendungsfälle,\r\n\r\nErste digitale BauFplo erhalten\r\n\r\nBaumaßnahmen, Züge, Linien oder Bereiche.\r\n\r\nEin Aussetzen ist jederzeit möglich\r\n\r\nFeedback senden\r\n\r\nEVU kann anhand der digitalen BauFplo ihre internen\r\n\r\nProzesse prüfen, da manuelle Anpassungen aufgrund\r\n\r\nDie Betriebserprobung ist die Gelegenheit, um sich\r\n\r\nFormatänderung notwendig sein können\r\n\r\nbereits jetzt mit dem neuen Format vertraut zu\r\n\r\nmachen und verschiedene Anwendungsfälle zu erproben!\r\n\r\nDB InfraGO AG | EVU Informationsveranstaltung | Neuerungen im Baufahrplan 2027 | 27.11.2025 37",126,"{\"canonical_url\":null,\"normalized_sha256\":\"b8dac29882ca03410182ee1cc3877874bf2603fc3814432a56926812715f7939\",\"page\":37,\"source_id\":\"src_6564bb0ccae19080edd4\",\"source_sha256\":\"61e0fd780a0643eded9510e89a8b1c4b4f982a6742e50fb2379ef7390cde57e3\",\"source_version_id\":\"sv_9911c8dfe35973048b5d6173\"}","1884595d6036b5255cfb3d7a2437b88455668e931bb7fcf80fdce04c46e6a0e6"],["chunk_fbeff1dd8757bb51a911221e","wiki/sources/unterlage-vertiefung-ujbau-27-11-data.md",37,"Seite 38","Ihre bisherigen Top-Fragen zur digitalen BauFplo auf einen Blick\r\n\r\nFrage Antwort\r\n\r\nWann erfolgt die finale Umstellung auf Die finale Umstellung auf die BauFplo erfolgt zum Oktober 2026. Wird ein FPE von Annex VII\r\n\r\ndie digitale BauFplo? verschickt, erfolgt automatisch die BauFplo im neuen Trassensicht-Format.\r\n\r\nWie sieht der Hochlauf in 2026 genau In 2026 kann die BauFplo sowohl im alten als auch im neuen Format erhalten werden.\r\n\r\naus? Was erwartet uns als EVUs? Bis zum Oktober 2026 muss jedoch die Komplettumstellung auf die digitale BauFplo erfolgen.\r\n\r\nWieso nutzen wir in der Derzeit ist eine Komplett-Umstellung auf ein System nicht möglich, da wir noch in den\r\n\r\nBetriebserprobung zwei Systeme (Alt- Vorprodukten ZvF und ÜB arbeiten und aus diesem Grund Trassen mehrfach erstellen müssten.\r\n\r\nund Neusystem) parallel? Wichtig ist jedoch: Eine BauFplo wird immer nur über ein System (und nicht doppelt) versendet.\r\n\r\nKann ich mir alle Züge meines EVUs In der Betriebserprobung erfolgt eine individuelle Abstimmung zwischen EVU und dem\r\n\r\nwünschen oder nur bestimmte jeweiligen Konstrukteur zu geeigneten Zügen ausgewählt. Bei einem gewünschten Hochlauf ist\r\n\r\nZugnummern? ebenfalls eine Vorabstimmung sinnvoll.\r\n\r\nGibt es die BauFplo auch für Havarie-\r\n\r\nAb Fahrplanjahr 2027 wird auch die Havarie im neuen Format und somit an der Schnittstelle zur\r\n\r\nFplon oder werden diese im alten Format\r\n\r\nVerfügung gestellt.\r\n\r\ngesendet?\r\n\r\nDB InfraGO AG | EVU Informationsveranstaltung | Neuerungen im Baufahrplan 2027 | 27.11.2025 38",224,"{\"canonical_url\":null,\"normalized_sha256\":\"b8dac29882ca03410182ee1cc3877874bf2603fc3814432a56926812715f7939\",\"page\":38,\"source_id\":\"src_6564bb0ccae19080edd4\",\"source_sha256\":\"61e0fd780a0643eded9510e89a8b1c4b4f982a6742e50fb2379ef7390cde57e3\",\"source_version_id\":\"sv_9911c8dfe35973048b5d6173\"}","e23c9926719fb7f974f03c6a30c965aee5ca694da4576f62538849b67d4ae43b"]]');
